import heapq


def _ledger(revision_priority, tax_base):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if revision_priority == "sequence_first":
                rank = (sequence, event.get("revision", 0), position)
            else:
                rank = (event.get("revision", 0), position)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, denominator=10000):
            if mode == "half_up":
                return (n + denominator // 2) // denominator
            return n // denominator

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if tax_base == "discounted" else raw
            tax = rounded(base * event.get("tax_bp", 0))
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + versions)

    best_vector = None
    best = None
    for assignment in product(*choices):
        selected = {name: version for name, version in zip(names, assignment)
                    if version is not None}
        valid = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in selected}
        for name, version in selected.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Only packages reachable from roots belong to the installation.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        state, cyclic = {}, False
        def visit(name):
            nonlocal cyclic
            if state.get(name) == 1:
                cyclic = True
                return
            if state.get(name) == 2 or cyclic:
                return
            state[name] = 1
            for target in edges.get(name, []):
                visit(target)
            state[name] = 2
        for name in selected:
            visit(name)
        if cyclic:
            continue

        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best = vector, selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    by_id = {job["id"]: job for job in jobs}
    if mandatory & blocked:
        return {"error": "impossible"}
    eligible = [job for job in jobs if job["id"] not in blocked]
    if len(eligible) < k or not mandatory.issubset({j["id"] for j in eligible}):
        return {"error": "impossible"}

    best_ids = None
    best_value = None
    for subset in __import__("itertools").combinations(eligible, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        overlap_ok = True
        for job in subset:
            time = job["start"]
            if sum(other["start"] <= time < other["end"] for other in subset) > 2:
                overlap_ok = False
                break
        if not overlap_ok:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


